    public CodemoveCtx clone() {
        CodemoveCtx cloneObj = new CodemoveCtx();
        cloneObj.work = new Work();
        cloneObj.work.set(work.getClonedField());
        cloneObj.employeeRecord = new EmployeeRecord();
        cloneObj.employeeRecord.set(employeeRecord.getClonedField());
        cloneObj.empRecord = new EmpRecord();
        cloneObj.empRecord.set(empRecord.getClonedField());
        return cloneObj;
    }

